mapper.select:
select sw.id, sw.warehouse_name as warehouseName, sw.warehouse_type as warehouseType, bui.name as keeper, sw.current_weight as currentWeight, sw.max_weight as maxWeight, sw.state, (select label from base_dict_data where type = 'GRAIN_VARIETY' and description = sw.grain_variety) as grainVariety from sts_warehouse sw left join base_user_info bui on bui.id = sw.keeper
and sw.id like concat('%', #{id}, '%')
and sw.warehouse_name like concat('%', #{warehouseName}, '%')
and sw.warehouse_type = #{warehouseType}
and sw.grain_variety = #{grainVariety}
and sw.state = #{state}
order by sw.add_time desc
